# /etc/keepalived/keepalived.conf on the PRIMARY node
global_defs {
    enable_script_security
    script_user keepalived_script
}
vrrp_script chk_service {
    script "/usr/bin/systemctl is-active --quiet nginx"
    interval 2
    fall 2
    rise 2
}
vrrp_instance VI_1 {
    state MASTER
    interface eth0              # replace with your NIC name
    virtual_router_id 51
    priority 150                # BACKUP node: state BACKUP, priority 100
    advert_int 1
    authentication {
        auth_type PASS
        auth_pass <CHANGE_ME>     # max 8 characters; use a unique value
    }
    virtual_ipaddress {
        192.0.2.100/24          # replace with a free address in your subnet
    }
    track_script {
        chk_service
    }
}
# then on both nodes:
#   sudo useradd -r -s /sbin/nologin keepalived_script
#   sudo systemctl enable --now keepalived
